var e=JSON.parse(`[{"id":"n_1","type":"subtitle","speaker":null,"text":{"KOREA":"CCN No. BDM003M000027-03\\n<color=#ffd34c>1급 요인</color> 열람 승인 자료\\n부록: 대상자 진술","JPN":"CCN No. BDM003M000027-03\\n<color=#ffd34c>1級要因</color> 閲覧承認資料\\n付録: 対象者陳述","ENG":"CCN No. BDM003M000027-03\\n<color=#ffd34c>Class 1 Entity</color> Access Approval Document\\nAppendix: Subject Testimony","TWN":"(TWN)CCN No. BDM003M000027-03\\n<color=#ffd34c>1급 요인</color> 열람 승인 자료\\n부록: 대상자 진술"},"stage":{"bg":"BLACK","bg_animation":null,"bgm":null,"filter":"NCFT_NORMAL","slots":{"L":null,"C":null,"R":null}}},{"id":"n_4","type":"dialog","speaker":"LIV_ZODIAC_NULL_NULL","text":{"KOREA":"아저씨, 컨셉종자가 무슨 뜻이야?","JPN":"おじさん、コンセプト種子が何の意味だ?","ENG":"Mister, what do you mean by \\"concept seeds\\"?","TWN":"(TWN)아저씨, 컨셉종자가 무슨 뜻이야?"},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":{"char_id":"LIV_ZODIAC_NULL_NULL","face":"UNIT_IDLE","hologram":false},"C":null,"R":null}}},{"id":"n_5","type":"dialog","speaker":"MERCENARY_VOICE_NULL_NULL","text":{"KOREA":"너네 같이 자기가 특별한 척 까부는 녀석들을 부르는 말이지.","JPN":"お前ら一緒に自分が特別なぴったりとふざける野郎どもを呼ぶ言葉だ。","ENG":"It's what we call people like you who act like you're something special.","TWN":"(TWN)너네 같이 자기가 특별한 척 까부는 녀석들을 부르는 말이지."},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":{"char_id":"LIV_ZODIAC_NULL_NULL","face":"UNIT_IDLE","hologram":false},"C":null,"R":{"char_id":"MERCENARY_VOICE_NULL_NULL","face":"UNIT_IDLE","hologram":false}}}},{"id":"n_6","type":"dialog","speaker":"LIV_ZODIAC_NULL_NULL","text":{"KOREA":"세계 평화를 위해 싸우는 사람들이란 거네?","JPN":"世界平和のために戦う人々ということだね?","ENG":"You mean people who fight for world peace?","TWN":"(TWN)세계 평화를 위해 싸우는 사람들이란 거네?"},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":{"char_id":"LIV_ZODIAC_NULL_NULL","face":"UNIT_IDLE","hologram":false},"C":null,"R":{"char_id":"MERCENARY_VOICE_NULL_NULL","face":"UNIT_IDLE","hologram":false}}}},{"id":"n_7","type":"dialog","speaker":"MERCENARY_VOICE_NULL_NULL","text":{"KOREA":"......저기 말이다. 뭔가 단단히 착각하나 본데 우린 목숨 걸고 돈 벌러 온 거라고.","JPN":"......あの言葉である。何か固く勘違いするようだったのですが私たちは命がけでお金稼ぎに来たことと。","ENG":"...Listen. You seem to be gravely mistaken, but we're here risking our lives to make money.","TWN":"(TWN)......저기 말이다. 뭔가 단단히 착각하나 본데 우린 목숨 걸고 돈 벌러 온 거라고."},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":{"char_id":"LIV_ZODIAC_NULL_NULL","face":"UNIT_IDLE","hologram":false},"C":null,"R":{"char_id":"MERCENARY_VOICE_NULL_NULL","face":"UNIT_IDLE","hologram":false}}}},{"id":"n_8","type":"dialog","speaker":"LIV_ZODIAC_NULL_NULL","text":{"KOREA":"그렇구나.","JPN":"そうであるね。","ENG":"I see.","TWN":"(TWN)그렇구나."},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":{"char_id":"LIV_ZODIAC_NULL_NULL","face":"UNIT_IDLE","hologram":false},"C":null,"R":{"char_id":"MERCENARY_VOICE_NULL_NULL","face":"UNIT_IDLE","hologram":false}}}},{"id":"n_9","type":"dialog","speaker":"MERCENARY_VOICE_NULL_NULL","text":{"KOREA":"그런 거지. 애초에 세계 평화 같은 헛소리는 어디서 나오는 거야?","JPN":"そんなことだ。最初に世界平和のようなうわごとはどこでナオはことなの?","ENG":"That's right. Where do you even get nonsense like \\"world peace\\" from?","TWN":"(TWN)그런 거지. 애초에 세계 평화 같은 헛소리는 어디서 나오는 거야?"},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":{"char_id":"LIV_ZODIAC_NULL_NULL","face":"UNIT_IDLE","hologram":false},"C":null,"R":{"char_id":"MERCENARY_VOICE_NULL_NULL","face":"UNIT_IDLE","hologram":false}}}},{"id":"n_10","type":"dialog","speaker":"LIV_ZODIAC_NULL_NULL","text":{"KOREA":"우리 단장이랑 부단장. 볼 때마다 세계 평화를 위해 싸워야 한다고 그러거든.","JPN":"私たちの団長と副団長。見る度に世界平和のために戦わなければならないとそうしたら。","ENG":"From our Captain and Vice-Captain. Every time I see them, they say we have to fight for world peace.","TWN":"(TWN)우리 단장이랑 부단장. 볼 때마다 세계 평화를 위해 싸워야 한다고 그러거든."},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":{"char_id":"LIV_ZODIAC_NULL_NULL","face":"UNIT_IDLE","hologram":false},"C":null,"R":{"char_id":"MERCENARY_VOICE_NULL_NULL","face":"UNIT_IDLE","hologram":false}}}},{"id":"n_11","type":"dialog","speaker":"MERCENARY_VOICE_NULL_NULL","text":{"KOREA":"윗대가리들부터 맛이 갔구만....","JPN":"上頭からいたんだんだな....","ENG":"So the brass has lost their minds...","TWN":"(TWN)윗대가리들부터 맛이 갔구만...."},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":{"char_id":"LIV_ZODIAC_NULL_NULL","face":"UNIT_IDLE","hologram":false},"C":null,"R":{"char_id":"MERCENARY_VOICE_NULL_NULL","face":"UNIT_IDLE","hologram":false}}}},{"id":"n_12","type":"dialog","speaker":"LIV_ZODIAC_NULL_NULL","text":{"KOREA":"그리고 나도 그렇게 생각해!","JPN":"そして私もそのように思う!","ENG":"And I believe in it too!","TWN":"(TWN)그리고 나도 그렇게 생각해!"},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":{"char_id":"LIV_ZODIAC_NULL_NULL","face":"UNIT_IDLE","hologram":false},"C":null,"R":{"char_id":"MERCENARY_VOICE_NULL_NULL","face":"UNIT_IDLE","hologram":false}}}},{"id":"n_13","type":"dialog","speaker":"MERCENARY_VOICE_NULL_NULL","text":{"KOREA":"......그냥 골고루 맛이 갔잖아. 소문이 정말이었어.","JPN":"......そのまま均等にいたんだんじゃないの。うわさが本当だった。","ENG":"...So you're all equally messed up. The rumors were true.","TWN":"(TWN)......그냥 골고루 맛이 갔잖아. 소문이 정말이었어."},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":{"char_id":"LIV_ZODIAC_NULL_NULL","face":"UNIT_IDLE","hologram":false},"C":null,"R":{"char_id":"MERCENARY_VOICE_NULL_NULL","face":"UNIT_IDLE","hologram":false}}}},{"id":"n_14","type":"dialog","speaker":"LIV_ZODIAC_NULL_NULL","text":{"KOREA":"소문? 우리 명성이 그렇게 높았어? 굉장한데!","JPN":"うわさ?私たちの名声がそのように高かった?すごいが!","ENG":"Rumors? Our reputation was that great? That's amazing!","TWN":"(TWN)소문? 우리 명성이 그렇게 높았어? 굉장한데!"},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":{"char_id":"LIV_ZODIAC_NULL_NULL","face":"UNIT_IDLE","hologram":false},"C":null,"R":{"char_id":"MERCENARY_VOICE_NULL_NULL","face":"UNIT_IDLE","hologram":false}}}},{"id":"n_15","type":"dialog","speaker":"MERCENARY_VOICE_NULL_NULL","text":{"KOREA":"그래. 기사단 놀이 하면서 공짜로 침식체 잡아 주는 바보들이 있다고 그러더라.","JPN":"そう。騎士団夕焼けがして無料で侵食体取ってくれる馬鹿があるとそうしていたよ。","ENG":"Yeah. They say there are fools playing at knights who hunt erosion creatures for free.","TWN":"(TWN)그래. 기사단 놀이 하면서 공짜로 침식체 잡아 주는 바보들이 있다고 그러더라."},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":{"char_id":"LIV_ZODIAC_NULL_NULL","face":"UNIT_IDLE","hologram":false},"C":null,"R":{"char_id":"MERCENARY_VOICE_NULL_NULL","face":"UNIT_IDLE","hologram":false}}}},{"id":"n_16","type":"dialog","speaker":"MERCENARY_VOICE_NULL_NULL","text":{"KOREA":"하긴 쥐꼬리만 한 회사가 무슨 돈으로 실력 있는 카운터를 고용하겠어.\\n다 공짜라니까 좋다고......","JPN":"そういえばわずかばかりの会社が何のお金で実力のあるカウンターを雇う。\\nすべて無料だって良いと......","ENG":"Guess a tiny company couldn't afford skilled Counters anyway.\\nSince it's all free, good for them...","TWN":"(TWN)하긴 쥐꼬리만 한 회사가 무슨 돈으로 실력 있는 카운터를 고용하겠어.\\n다 공짜라니까 좋다고......"},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":{"char_id":"LIV_ZODIAC_NULL_NULL","face":"UNIT_IDLE","hologram":false},"C":null,"R":{"char_id":"MERCENARY_VOICE_NULL_NULL","face":"UNIT_IDLE","hologram":false}}}},{"id":"n_17","type":"dialog","speaker":null,"text":{"KOREA":"전방에 침식체 발견! 1종이다! 거리는 500!","JPN":"前方に侵食体発見!1種である!距離は500!","ENG":"Erosion creature detected ahead! It's Class 1! Distance 500!","TWN":"(TWN)전방에 침식체 발견! 1종이다! 거리는 500!"},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":null,"C":null,"R":null}},"sfx":"FX_CUTSCEN_NOISE"},{"id":"n_18","type":"dialog","speaker":null,"text":{"KOREA":"다들 무기 챙겨! 오늘 한탕 두둑하게 챙겨서 가야지!","JPN":"みんな武器得る!今日一発分厚く得て行かなくてはならない!","ENG":"Everyone grab your weapons! We're gonna score big today!","TWN":"(TWN)다들 무기 챙겨! 오늘 한탕 두둑하게 챙겨서 가야지!"},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":null,"C":null,"R":null}}},{"id":"n_20","type":"dialog","speaker":"MERCENARY_VOICE_NULL_NULL","text":{"KOREA":"들었지, 기사님. 이제부턴 너랑 어울려 줄 시간 없겠다.","JPN":"きいたの、技師様。今からは君と似合ってくれる時間ない。","ENG":"You heard that, Knight. From here on out, I don't have time to babysit you.","TWN":"(TWN)들었지, 기사님. 이제부턴 너랑 어울려 줄 시간 없겠다."},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":null,"C":null,"R":{"char_id":"MERCENARY_VOICE_NULL_NULL","face":"UNIT_IDLE","hologram":false}}}},{"id":"n_21","type":"dialog","speaker":"LIV_ZODIAC_NULL_NULL","text":{"KOREA":"아저씨, 진짜 싸우게? 위험할 것 같은데?","JPN":"おじさん、本当に戦いなさい?危ないようなところ?","ENG":"Mister, are you really going to fight? It looks dangerous.","TWN":"(TWN)아저씨, 진짜 싸우게? 위험할 것 같은데?"},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":{"char_id":"LIV_ZODIAC_NULL_NULL","face":"UNIT_IDLE","hologram":false},"C":null,"R":{"char_id":"MERCENARY_VOICE_NULL_NULL","face":"UNIT_IDLE","hologram":false}}}},{"id":"n_22","type":"dialog","speaker":"MERCENARY_VOICE_NULL_NULL","text":{"KOREA":"나 참. 고작 1종인데 위험하긴 무슨.\\n무서우면 뒤에 붙어다니기나 해, 기사님.","JPN":"私さて。せいぜい1種だが危ないことは何の.\\n恐ろしければ後に付き添いもして、技師様。","ENG":"Come on. It's just a Class 1, what's dangerous about it?\\nIf you're scared, stay in the back, Knight.","TWN":"(TWN)나 참. 고작 1종인데 위험하긴 무슨.\\n무서우면 뒤에 붙어다니기나 해, 기사님."},"stage":{"bg":"CITY_STREET_NORMAL","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":{"char_id":"LIV_ZODIAC_NULL_NULL","face":"UNIT_IDLE","hologram":false},"C":null,"R":{"char_id":"MERCENARY_VOICE_NULL_NULL","face":"UNIT_IDLE","hologram":false}}}},{"id":"n_25","type":"dialog","speaker":"MERCENARY_VOICE_NULL_NULL","text":{"KOREA":"그 카운터 말대로, 함정이었습니다.","JPN":"そのカウンター言葉通り、罠でした。","ENG":"As that Counter said, it was a trap.","TWN":"(TWN)그 카운터 말대로, 함정이었습니다."},"stage":{"bg":"BLACK","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":null,"C":null,"R":null}}},{"id":"n_26","type":"dialog","speaker":"MERCENARY_VOICE_NULL_NULL","text":{"KOREA":"제 1종을 미끼로 던지고 진을 친 채로 기다렸던 거죠.\\n섬뜩할 만큼 교활한 놈들이었습니다.","JPN":"第1種を餌で投げて陣を張ったまま待ったことですよ。\\n薄気味悪いくらい狡いやつでした。","ENG":"They had used Class 1 as bait and waited in ambush.\\nThey were terrifyingly cunning.","TWN":"(TWN)제 1종을 미끼로 던지고 진을 친 채로 기다렸던 거죠.\\n섬뜩할 만큼 교활한 놈들이었습니다."},"stage":{"bg":"BLACK","bg_animation":null,"bgm":"CUTSCENE_TALK_01","filter":"NCFT_NORMAL","slots":{"L":null,"C":null,"R":null}}}]`);export{e as default};